typedef struct {
    int* keys;
    bool* used;
    size_t mask;
} IntSet;

static size_t set_slot(const IntSet* s, int key) {
    size_t i = ((uint32_t)key * 2654435761u) & s->mask;
    while (s->used[i] && s->keys[i] != key) i = (i + 1) & s->mask;
    return i;
}

static bool set_has(const IntSet* s, int key) {
    return s->used[set_slot(s, key)];
}

int longestRun(const int* nums, int n) {
    size_t cap = 16;
    while (cap < 2 * (size_t)n) cap <<= 1;
    IntSet values = {malloc(cap * sizeof(int)), calloc(cap, sizeof(bool)), cap - 1};
    for (int i = 0; i < n; i++) {
        size_t j = set_slot(&values, nums[i]);
        values.used[j] = true;
        values.keys[j] = nums[i];
    }
    int best = 0;
    for (size_t j = 0; j <= values.mask; j++) {
        if (!values.used[j]) continue;
        int x = values.keys[j];
        if (set_has(&values, x - 1)) continue;
        int length = 1;
        while (set_has(&values, x + length)) length++;
        if (length > best) best = length;
    }
    free(values.keys);
    free(values.used);
    return best;
}

