static int longestWithOneAdded(int[] nums) {
    Set<Integer> values = new HashSet<>();
    for (int x : nums) values.add(x);
    Map<Integer, Integer> runs = new HashMap<>();
    for (int x : values) {
        if (values.contains(x - 1)) continue;
        int length = 1;
        while (values.contains(x + length)) length++;
        runs.put(x, length);
    }
    int best = 0;
    for (Map.Entry<Integer, Integer> e : runs.entrySet()) {
        int start = e.getKey(), length = e.getValue();
        int after = start + length + 1;
        best = Math.max(best, length + 1 + runs.getOrDefault(after, 0));
    }
    return best;
}

