int longestWithOneAdded(const vector<int>& nums) {
    unordered_set<int> values(nums.begin(), nums.end());
    unordered_map<int, int> runs;
    for (int x : values) {
        if (values.count(x - 1)) continue;
        int length = 1;
        while (values.count(x + length)) length++;
        runs[x] = length;
    }
