typedef struct {
    int *keys, *vals;
    bool* used;
    size_t mask;
} IntMap;

static IntMap map_new(int n) {
    size_t cap = 16;
    while (cap < 2 * (size_t)n) cap <<= 1;
    IntMap m = {malloc(cap * sizeof(int)), malloc(cap * sizeof(int)), calloc(cap, sizeof(bool)), cap - 1};
    return m;
}

static size_t map_slot(const IntMap* m, int key) {
    size_t i = ((uint32_t)key * 2654435761u) & m->mask;
    while (m->used[i] && m->keys[i] != key) i = (i + 1) & m->mask;
    return i;
}

static void map_put(IntMap* m, int key, int val) {
    size_t i = map_slot(m, key);
    m->used[i] = true;
    m->keys[i] = key;
    m->vals[i] = val;
}

static int map_get(const IntMap* m, int key, int missing) {
    size_t i = map_slot(m, key);
    return m->used[i] ? m->vals[i] : missing;
}

int longestWithOneAdded(const int* nums, int n) {
    IntMap values = map_new(n), runs = map_new(n);
    for (int i = 0; i < n; i++) map_put(&values, nums[i], 1);
    for (size_t j = 0; j <= values.mask; j++) {
        if (!values.used[j]) continue;
        int x = values.keys[j];
        if (map_get(&values, x - 1, 0)) continue;
        int length = 1;
        while (map_get(&values, x + length, 0)) length++;
        map_put(&runs, x, length);
    }
    int best = 0;
    for (size_t j = 0; j <= runs.mask; j++) {
        if (!runs.used[j]) continue;
        int start = runs.keys[j], length = runs.vals[j];
        int after = start + length + 1;
        int total = length + 1 + map_get(&runs, after, 0);
        if (total > best) best = total;
    }
    free(values.keys); free(values.vals); free(values.used);
    free(runs.keys); free(runs.vals); free(runs.used);
    return best;
}
